import {catalogGroups,topicMatch,isReadableDoc} from './catalog-data.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const materialOptions=[['code','코드 있는 자료만'],['reference','코드 없는 참고 자료'],['notes','Notion·학습 문서'],['complete','전체 코드가 있는 문서'],['files','GitHub 원본 파일'],['all','모든 자료']];
export function filterMaterial(d,value){return value==='code'?d.codeInfo?.hasCode:value==='reference'?!d.codeInfo?.hasCode&&d.codeInfo?.kind!=='empty':value==='notes'?isReadableDoc(d):value==='complete'?d.recipe:value==='files'?d.source==='GitHub'&&!d.id.startsWith('ghp-'):true;}
export function filterCatalog(list,{groupId='',topicId='',material='notes'}){return list.filter(d=>filterMaterial(d,material)&&topicMatch(d,groupId,topicId));}
export function catalogBrowser(docs,{groupId='',topicId='',material='notes',query='',mode='all'}){const group=catalogGroups.find(g=>g.id===groupId),topic=group?.topics.find(t=>t.id===topicId),base=docs.filter(d=>filterMaterial(d,material)&&(mode!=='recipes'||d.recipe));const crumbs=`<div class="catalog-crumbs"><button data-catalog-home>전체 작업</button>${group?`<span>›</span><button data-catalog-group="${group.id}">${esc(group.title)}</button>`:''}${topic?`<span>›</span><strong>${esc(topic.title)}</strong>`:''}</div>`;
if(query)return `${crumbs}<div class="catalog-search-note">${group?esc(group.title)+' 안에서':'모든 작업에서'} 검색하고 있어요. <button data-catalog-clear-search>검색어 지우기</button></div>`;
if(!group)return `<div class="catalog-intro"><h2>할 일을 먼저 고르세요</h2><p>영문 이름을 몰라도 괜찮아요. 아래 작업에서 세부 기능으로 들어갈 수 있어요.</p></div><nav class="catalog-start" aria-label="자주 찾는 시작점"><button data-catalog-topic="field-lab/map">새로 보강한 30편</button><span>처음이라면</span><button data-catalog-topic="screen/basic">첫 조회 화면 만들기</button><span>표를 고치려면</span><button data-catalog-topic="alv/rows">행 선택·추가·삭제</button><span>버튼이 안 되면</span><button data-catalog-topic="screen/flow">화면·버튼 처리 순서</button></nav><div class="catalog-groups">${catalogGroups.map((g,i)=>{const count=base.filter(d=>topicMatch(d,g.id,'')).length;return `<button class="catalog-group" data-catalog-group="${g.id}"><span class="catalog-number">${String(i+1).padStart(2,'0')}</span><strong>${esc(g.title)}</strong><p>${esc(g.description)}</p><small>${g.topics.length}개 세부 작업 · 문서 ${count}개</small><span class="catalog-technical">${esc(g.technical)}</span></button>`}).join('')}</div><div class="catalog-source-note"><strong>원본 파일이 필요하면</strong><p>읽을 자료를 “GitHub 원본 파일” 또는 “모든 자료”로 바꾸세요. 기본 목록에는 실제 코드가 있는 자료만 표시합니다. 설명·목차·캡처는 “코드 없는 참고 자료”에서 확인하세요.</p></div>`;
return `${crumbs}<div class="catalog-intro"><h2>${esc(group.title)}</h2><p>${esc(group.description)}</p></div><div class="catalog-topics"><button class="catalog-topic ${!topicId?'active':''}" data-catalog-group="${group.id}"><strong>이 분류 전체 보기</strong><span>설명과 예제를 함께 찾아보기</span><small>${base.filter(d=>topicMatch(d,group.id,'')).length}개 문서</small></button>${group.topics.map(t=>{const count=base.filter(d=>topicMatch(d,group.id,t.id)).length;return `<button class="catalog-topic ${topicId===t.id?'active':''}" ${group.id==='events'&&t.id==='f4'?'data-event-open="alv-onf4"':`data-catalog-topic="${group.id}/${t.id}"`}><strong>${esc(t.title)}</strong><span>${esc(t.description)}</span><small>${group.id==='events'&&t.id==='f4'?'이벤트 설명·등록 위치':count?count+'개 문서':'해당 자료 없음 · 원본 파일에서도 찾아보세요'}</small></button>`}).join('')}</div>${topic?`<div class="catalog-current"><h3>${esc(topic.title)}</h3><p>${esc(topic.description)} · 아래 문서를 선택해 읽으세요.</p></div>`:'<div class="catalog-current"><h3>이 작업의 문서</h3><p>전체 코드가 있는 예제를 먼저 보여줘요. 세부 작업을 고르면 목록이 더 좁아져요.</p></div>'}`;}
export const catalogTitle=id=>catalogGroups.find(g=>g.id===id)?.title||'';
